/**
 * Memory contracts.
 *
 * Before this existed, "memory" meant the browser fetching 50 documents from
 * Firestore and computing cosine similarity client-side, with embeddings
 * generated by an undocumented model. Nothing was server-side, nothing was
 * rankable at scale, and there was no structured model of the user at all.
 */

export interface MemoryRecord {
  id: string;
  /** Owning user (Firebase uid). */
  userId: string;
  text: string;
  /** Embedding vector, when one could be generated. */
  embedding: number[];
  /** Free-form tags, e.g. ['project:arc', 'preference']. */
  tags: string[];
  /** ISO timestamp. */
  createdAt: string;
}

export interface UserProfile {
  userId: string;
  /** How the user prefers to be addressed. */
  preferredName?: string;
  timezone?: string;
  /** Free-form facts the user has stated: role, projects, devices, preferences. */
  facts: string[];
  /** Local hours during which the assistant must not interrupt (0-23). */
  quietHours?: { startHour: number; endHour: number };
  updatedAt: string;
}

export interface Episode {
  id: string;
  userId: string;
  /** One-line summary of what happened. */
  summary: string;
  /** ISO timestamp. */
  at: string;
}

export interface NewMemory {
  userId: string;
  text: string;
  embedding?: number[];
  tags?: string[];
}

export interface ScoredMemory {
  record: MemoryRecord;
  /** Cosine similarity in [-1, 1]; 0 when either vector is missing. */
  score: number;
  /** True when the score came from lexical overlap rather than embeddings. */
  lexical?: boolean;
}

/**
 * Storage backend. Implementations must be safe to call concurrently.
 * A Firestore-backed store is used when credentials are available; the
 * in-process store is an explicit, non-durable fallback.
 */
export interface MemoryStore {
  /** Human-readable name, surfaced in /api/health. */
  readonly kind: 'firestore' | 'in-memory';
  /** True when data survives a process restart. */
  readonly durable: boolean;

  addMemory(record: MemoryRecord): Promise<void>;
  listMemories(userId: string, limit: number): Promise<MemoryRecord[]>;
  deleteMemory(userId: string, id: string): Promise<boolean>;

  getProfile(userId: string): Promise<UserProfile | null>;
  saveProfile(profile: UserProfile): Promise<void>;

  addEpisode(episode: Episode): Promise<void>;
  listEpisodes(userId: string, limit: number): Promise<Episode[]>;
}
